<script setup>
import { computed } from "vue"; import AdminLayout from "../components/admin/AdminLayout.vue"; import DataTable from "../components/DataTable.vue"; import { useServerTable } from "../services/serverTable"; import { t } from "../services/i18n";
const { items, loading, pagination, load } = useServerTable({ endpoint: "/api/v1/admin/stock_movements", collectionKey: "stock_movements" });
const columns = computed(() => [{key:"product_name",label:t("products.name"),sortable:false},{key:"movement_type",label:t("stock.type")},{key:"stock_before",label:t("stock.before"),sortable:false},{key:"quantity",label:t("stock.quantity")},{key:"stock_after",label:t("stock.after")},{key:"note",label:t("stock.note"),sortable:false},{key:"user_email",label:t("stock.officer"),sortable:false},{key:"created_at",label:t("stock.time")}]);
const typeLabel = (type) => ({initial:"stock.initial",adjustment_in:"stock.increase",adjustment_out:"stock.decrease",damaged:"stock.damaged",lost:"stock.lost",internal_use:"stock.internal_use"}[type] || type);
</script>
<template><AdminLayout><div class="mx-auto max-w-[1536px]"><div class="mb-6"><h1 class="text-2xl font-semibold dark:text-white">{{t('stock.movements_title')}}</h1><p class="mt-1 text-sm text-gray-500">{{t('stock.movements_subtitle')}}</p></div><DataTable :items="items" :columns="columns" :loading="loading" :empty-text="t('stock.empty_movements')" server-mode :total="pagination.total" @request="load"><template #cell-product_name="{item}"><strong class="dark:text-white">{{item.product_name}}</strong></template><template #cell-movement_type="{item}">{{t(typeLabel(item.movement_type))}}</template><template #cell-quantity="{item}"><span :class="item.quantity > 0 ? 'text-brand-600' : 'text-error-600'">{{item.quantity > 0 ? '+' : ''}}{{item.quantity}}</span></template><template #cell-created_at="{item}">{{new Date(item.created_at).toLocaleString()}}</template></DataTable></div></AdminLayout></template>
